-- TABELA user

DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` int NOT NULL AUTO_INCREMENT,
  `Nome` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Cargo` varchar(70) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT ' ',
  `Email` varchar(60) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Senha` varchar(700) COLLATE utf8mb4_general_ci NOT NULL,
  `Inativo` tinyint(1) DEFAULT '0',
  `DataUtimoAcesso` datetime DEFAULT NULL,
  `IPUltimoAcesso` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Tipo` int NOT NULL DEFAULT '0',
  `idEmpresa` int NOT NULL,
  `AdminGeral` int NOT NULL DEFAULT '0',
  `tokenRecuperar` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT ' ',
  `tokenExpira` datetime DEFAULT CURRENT_TIMESTAMP,
  `EstadoCivil` int DEFAULT '0',
  `NumOAB` varchar(35) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `NumeroEndereco` varchar(70) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Cidade` varchar(60) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Documento` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Contato` varchar(60) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Rua` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `LogoBase64` longtext COLLATE utf8mb4_general_ci,
  `UF` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `CEP` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Bairro` varchar(70) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

